  const maxId = tasks.reduce((max, task) => Math.max(max, task.id), 0);
  if ((value.nextId as number) <= maxId) fail("Malformed database: nextId does not exceed existing ids");

  return { version: 1, nextId: value.nextId as number, tasks };
